275	    // ::comment etc
276	    private Evaluator parseNodeSelector() {
277	        final String pseudo = tq.consumeCssIdentifier();
278	        inNodeContext = true;  // Enter node context
279	
280	        Evaluator left;
281	        switch (pseudo) {
282	            case "node":
283	                left = new NodeEvaluator.InstanceType(Node.class, pseudo);
284	                break;
285	            case "leafnode":
286	                left = new NodeEvaluator.InstanceType(LeafNode.class, pseudo);
287	                break;
288	            case "text":
289	                left = new NodeEvaluator.InstanceType(TextNode.class, pseudo);
290	                break;
291	            case "comment":
292	                left = new NodeEvaluator.InstanceType(Comment.class, pseudo);
293	                break;
294	            case "data":
295	                left = new NodeEvaluator.InstanceType(DataNode.class, pseudo);
296	                break;
297	            case "cdata":
298	                left = new NodeEvaluator.InstanceType(CDataNode.class, pseudo);
299	                break;
300	            default:
301	                throw new Selector.SelectorParseException(
302	                    "Could not parse query '%s': unknown node type '::%s'", query, pseudo);
303	        }
304	
305	        // Handle following subclasses in node context (like ::comment:contains())
306	        Evaluator right;
307	        while ((right = parseSubclass()) != null) {
308	            left = and(left, right);
309	        }
310	
311	        inNodeContext = false;
312	        return left;
313	    }
