315	    private Evaluator byId() {
316	        String id = tq.consumeCssIdentifier();
317	        Validate.notEmpty(id);
318	        return new Evaluator.Id(id);
319	    }
320	
321	    private Evaluator byClass() {
322	        String className = tq.consumeCssIdentifier();
323	        Validate.notEmpty(className);
324	        return new Evaluator.Class(className.trim());
325	    }
326	
327	    private Evaluator byTag() {
328	        // todo - these aren't dealing perfectly with case sensitivity. For case sensitive parsers, we should also make
329	        // the tag in the selector case-sensitive (and also attribute names). But for now, normalize (lower-case) for
330	        // consistency - both the selector and the element tag
331	        String tagName = normalize(tq.consumeElementSelector());
332	        Validate.notEmpty(tagName);
333	
334	        // namespaces:
335	        if (tagName.startsWith("*|")) { // namespaces: wildcard match equals(tagName) or ending in ":"+tagName
336	            String plainTag = tagName.substring(2); // strip *|
337	            return new CombiningEvaluator.Or(
338	                new Evaluator.Tag(plainTag),
339	                new Evaluator.TagEndsWith(":" + plainTag)
340	            );
341	        } else if (tagName.endsWith("|*")) { // ns|*
342	            String ns = tagName.substring(0, tagName.length() - 2) + ":"; // strip |*, to ns:
343	            return new Evaluator.TagStartsWith(ns);
344	        } else if (tagName.contains("|")) { // flip "abc|def" to "abc:def"
345	            tagName = tagName.replace("|", ":");
346	        }
347	
348	        return new Evaluator.Tag(tagName);
349	    }
350	
351	    private Evaluator byAttribute() {
352	        try (TokenQueue cq = new TokenQueue(tq.chompBalanced('[', ']'))) {
353	            return evaluatorForAttribute(cq);
354	        }
355	    }
356	
357	    private Evaluator evaluatorForAttribute(TokenQueue cq) {
358	        String key = cq.consumeToAny(AttributeEvals); // eq, not, start, end, contain, match, (no val)
359	        key = normalize(key);
360	        Validate.notEmpty(key);
361	        Validate.isFalse(key.equals("abs:"), "Absolute attribute key must have a name");
362	        cq.consumeWhitespace();
363	        final Evaluator eval;
364	
365	        if (cq.isEmpty()) {
366	            if (key.startsWith("^"))
367	                eval = new Evaluator.AttributeStarting(key.substring(1));
368	            else if (key.equals("*")) // any attribute
369	                eval = new Evaluator.AttributeStarting("");
370	            else
371	                eval = new Evaluator.Attribute(key);
372	        } else {
373	            if (cq.matchChomp('='))
374	                eval = new Evaluator.AttributeWithValue(key, cq.remainder());
375	            else if (cq.matchChomp("!="))
376	                eval = new Evaluator.AttributeWithValueNot(key, cq.remainder());
377	            else if (cq.matchChomp("^="))
378	                eval = new Evaluator.AttributeWithValueStarting(key, cq.remainder());
379	            else if (cq.matchChomp("$="))
380	                eval = new Evaluator.AttributeWithValueEnding(key, cq.remainder());
381	            else if (cq.matchChomp("*="))
382	                eval = new Evaluator.AttributeWithValueContaining(key, cq.remainder());
383	            else if (cq.matchChomp("~="))
384	                eval = new Evaluator.AttributeWithValueMatching(key, Regex.compile(cq.remainder()));
385	            else
386	                throw new Selector.SelectorParseException(
387	                    "Could not parse attribute query '%s': unexpected token at '%s'", query, cq.remainder());
388	        }
389	        return eval;
390	    }
