392	    //pseudo selectors :first-child, :last-child, :nth-child, ...
393	    private static final Pattern NthStepOffset = Pattern.compile("(([+-])?(\\d+)?)n(\\s*([+-])?\\s*\\d+)?", Pattern.CASE_INSENSITIVE);
394	    private static final Pattern NthOffset = Pattern.compile("([+-])?(\\d+)");
395	
396	    private Evaluator cssNthChild(boolean last, boolean ofType) {
397	        String arg = consumeParens(); // arg is like "odd", "-n+2", or "2 of .p", within nth-child(...)
398	
399	        // split off the optional Selectors L4 " of S" clause, if any
400	        int[] ofBounds = ofClauseBounds(arg);
401	        final String formula = normalize(ofBounds == null ? arg : arg.substring(0, ofBounds[0]));
402	        final String ofPart = ofBounds == null ? null : arg.substring(ofBounds[1]).trim();
403	
404	        if (ofPart != null && ofType)
405	            throw new Selector.SelectorParseException(
406	                "Could not parse query '%s': the :nth-%sof-type pseudo-class does not support the 'of S' selector",
407	                query, last ? "last-" : "");
408	
409	        final int step, offset;
410	        if ("odd".equals(formula)) {
411	            step = 2;
412	            offset = 1;
413	        } else if ("even".equals(formula)) {
414	            step = 2;
415	            offset = 0;
416	        } else {
417	            Matcher stepOffsetM, stepM;
418	            if ((stepOffsetM = NthStepOffset.matcher(formula)).matches()) {
419	                if (stepOffsetM.group(3) != null) // has digits, like 3n+2 or -3n+2
420	                    step = Integer.parseInt(stepOffsetM.group(1).replaceFirst("^\\+", ""));
421	                else // no digits, might be like n+2, or -n+2. if group(2) == "-", it’s -1;
422	                    step = "-".equals(stepOffsetM.group(2)) ? -1 : 1;
423	                offset =
424	                    stepOffsetM.group(4) != null ? Integer.parseInt(stepOffsetM.group(4).replaceFirst("^\\+", "")) : 0;
425	            } else if ((stepM = NthOffset.matcher(formula)).matches()) {
426	                step = 0;
427	                offset = Integer.parseInt(stepM.group().replaceFirst("^\\+", ""));
428	            } else {
429	                throw new Selector.SelectorParseException("Could not parse nth-index '%s': unexpected format", formula);
430	            }
431	        }
432	
433	        Evaluator filter = null;
434	        if (ofPart != null) {
435	            Validate.notEmpty(ofPart, ":nth-child(An+B of S) requires a selector after 'of'");
436	            filter = parse(ofPart); // a selector list, parsed by the same grammar (and validated in full)
437	        }
438	
439	        if (ofType)
440	            return last ? new Evaluator.IsNthLastOfType(step, offset) : new Evaluator.IsNthOfType(step, offset);
441	        return last
442	            ? new Evaluator.IsNthLastChild(step, offset, filter)
443	            : new Evaluator.IsNthChild(step, offset, filter);
444	    }
