446	    /**
447	     Finds the bounds of the optional top-level {@code  of S} clause in an nth-child argument. The {@code of} keyword is
448	     only recognized when it is outside of nested parens/brackets and quoted strings, so that an {@code of} nested inside
449	     the {@code S} selector (or inside a quoted attribute value) is not mistaken for the clause.
450	     @param arg the raw argument within nth-child( ... )
451	     @return {@code [formulaEnd exclusive, selectorStart inclusive]}, or {@code null} if there is no {@code of S} clause
452	     */
453	    private static int @Nullable [] ofClauseBounds(String arg) {
454	        int depth = 0;
455	        boolean inQuote = false;
456	        boolean escaped = false;
457	
458	        for (int i = 0; i < arg.length(); i++) {
459	            char c = arg.charAt(i);
460	            if (inQuote) {
461	                if (escaped) escaped = false;
462	                else if (c == '\\') escaped = true;
463	                else if (c == '\'' || c == '"') inQuote = false;
464	                continue;
465	            }
466	            if (c == '\'' || c == '"') { inQuote = true; continue; }
467	            if (c == '(' || c == '[' || c == '{') { depth++; continue; }
468	            if (c == ')' || c == ']' || c == '}') { depth--; continue; }
469	
470	            if (depth == 0 && arg.regionMatches(true, i, "of", 0, 2)
471	                && i > 0 && StringUtil.isWhitespace(arg.charAt(i - 1))
472	                && i + 2 < arg.length() && StringUtil.isWhitespace(arg.charAt(i + 2))) {
473	
474	                int formulaEnd = i - 1; // index of the whitespace delimiting the formula
475	                while (formulaEnd >= 0 && StringUtil.isWhitespace(arg.charAt(formulaEnd))) formulaEnd--;
476	
477	                int selectorStart = i + 3; // first char after the whitespace following "of"
478	                while (selectorStart < arg.length() && StringUtil.isWhitespace(arg.charAt(selectorStart))) selectorStart++;
479	
480	                if (formulaEnd >= 0 && selectorStart < arg.length())
481	                    return new int[] {formulaEnd + 1, selectorStart};
482	            }
483	        }
484	        return null;
485	    }
486	
487	    private String consumeParens() {
488	        return tq.chompBalanced('(', ')');
489	    }
490	
491	    private int consumeIndex() {
492	        String index = consumeParens().trim();
493	        Validate.isTrue(StringUtil.isNumeric(index), "Index must be numeric");
494	        return Integer.parseInt(index);
495	    }
