514	    // pseudo selector :contains(text), containsOwn(text)
515	    private Evaluator contains(boolean own) {
516	        String query = own ? ":containsOwn" : ":contains";
517	        String searchText = TokenQueue.unescape(consumeParens());
518	        Validate.notEmpty(searchText, query + "(text) query must not be empty");
519	
520	        if (inNodeContext)
521	            return new NodeEvaluator.ContainsValue(searchText);
522	
523	        return own
524	            ? new Evaluator.ContainsOwnText(searchText)
525	            : new Evaluator.ContainsText(searchText);
526	    }
527	
528	    private Evaluator containsWholeText(boolean own) {
529	        String query = own ? ":containsWholeOwnText" : ":containsWholeText";
530	        String searchText = TokenQueue.unescape(consumeParens());
531	        Validate.notEmpty(searchText, query + "(text) query must not be empty");
532	        return own
533	            ? new Evaluator.ContainsWholeOwnText(searchText)
534	            : new Evaluator.ContainsWholeText(searchText);
535	    }
536	
537	    // pseudo selector :containsData(data)
538	    private Evaluator containsData() {
539	        String searchText = TokenQueue.unescape(consumeParens());
540	        Validate.notEmpty(searchText, ":containsData(text) query must not be empty");
541	        return new Evaluator.ContainsData(searchText);
542	    }
543	
544	    // :matches(regex), matchesOwn(regex)
545	    private Evaluator matches(boolean own) {
546	        String query = own ? ":matchesOwn" : ":matches";
547	        String regex = consumeParens(); // don't unescape, as regex bits will be escaped
548	        Validate.notEmpty(regex, query + "(regex) query must not be empty");
549	        Regex pattern = Regex.compile(regex);
550	
551	        if (inNodeContext)
552	            return new NodeEvaluator.MatchesValue(pattern);
553	
554	        return own
555	            ? new Evaluator.MatchesOwn(pattern)
556	            : new Evaluator.Matches(pattern);
557	    }
558	
559	    // :matches(regex), matchesOwn(regex)
560	    private Evaluator matchesWholeText(boolean own) {
561	        String query = own ? ":matchesWholeOwnText" : ":matchesWholeText";
562	        String regex = consumeParens(); // don't unescape, as regex bits will be escaped
563	        Validate.notEmpty(regex, query + "(regex) query must not be empty");
564	
565	        Regex pattern = Regex.compile(regex);
566	        return own
567	            ? new Evaluator.MatchesWholeOwnText(pattern)
568	            : new Evaluator.MatchesWholeText(pattern);
569	    }
570	
571	    // :not(selector)
572	    private Evaluator not() {
573	        String subQuery = consumeParens();
574	        Validate.notEmpty(subQuery, ":not(selector) subselect must not be empty");
575	
576	        return new StructuralEvaluator.Not(parse(subQuery));
577	    }
