26	/**
27	 An Evaluator tests if an element (or a node) meets the selector's requirements. Obtain an evaluator for a given CSS selector
28	 with {@link Selector#evaluatorOf(String css)}. If you are executing the same selector on many elements (or documents), it
29	 can be more efficient to compile and reuse an Evaluator than to reparse the selector on each invocation of select().
30	 <p>Evaluators are thread-safe and may be used concurrently across multiple documents.</p>
31	 */
32	public abstract class Evaluator {
33	    protected Evaluator() {
34	    }
35	
36	    /**
37	     Provides a Predicate for this Evaluator, matching the test Element.
38	     * @param root the root Element, for match evaluation
39	     * @return a predicate that accepts an Element to test for matches with this Evaluator
40	     * @since 1.17.1
41	     */
42	    public Predicate<Element> asPredicate(Element root) {
43	        return element -> matches(root, element);
44	    }
45	
46	    Predicate<Node> asNodePredicate(Element root) {
47	        return node -> matches(root, node);
48	    }
49	
50	    /**
51	     * Test if the element meets the evaluator's requirements.
52	     *
53	     * @param root    Root of the matching subtree
54	     * @param element tested element
55	     * @return Returns <tt>true</tt> if the requirements are met or
56	     * <tt>false</tt> otherwise
57	     */
58	    public abstract boolean matches(Element root, Element element);
59	
60	    final boolean matches(Element root, Node node) {
61	        if (node instanceof Element) {
62	            return matches(root, (Element) node);
63	        } else if (node instanceof LeafNode && wantsNodes()) {
64	            return matches(root, (LeafNode) node);
65	        }
66	        return false;
67	    }
68	
69	    boolean matches(Element root, LeafNode leafNode) {
70	        return false;
71	    }
72	
73	    boolean wantsNodes() {
74	        return false;
75	    }
