83	    /**
84	     A relative evaluator cost function. During evaluation, Evaluators are sorted by ascending cost as an optimization.
85	     * @return the relative cost of this Evaluator
86	     */
87	    protected int cost() {
88	        return 5; // a nominal default cost
89	    }
