567	    public static abstract class CssNthEvaluator extends Evaluator {
568	        /** Step */
569	        protected final int a;
570	        /** Offset */
571	        protected final int b;
572	        /** Optional <code>of S</code> selector filter; when present, only siblings matching it are counted. */
573	        protected final @Nullable Evaluator filter;
574	
575	        public CssNthEvaluator(int step, int offset) {
576	            this(step, offset, null);
577	        }
578	
579	        public CssNthEvaluator(int step, int offset, @Nullable Evaluator filter) {
580	            this.a = step;
581	            this.b = offset;
582	            this.filter = filter;
583	        }
584	
585	        public CssNthEvaluator(int offset) {
586	            this(0, offset, null);
587	        }
588	
589	        @Override
590	        public boolean matches(Element root, Element element) {
591	            final Element p = element.parent();
592	            if (p == null || (p instanceof Document)) return false;
593	            if (filter != null && !filter.matches(root, element))
594	                return false; // the element itself must be one of the of S siblings
595	
596	            final int pos = calculatePosition(root, element);
597	            if (a == 0) return pos == b;
598	
599	            return (pos - b) * a >= 0 && (pos - b) % a == 0;
600	        }
601	
602	        @Override
603	        public String toString() {
604	            String format =
605	                (a == 0) ? ":%s(%3$d)"    // only offset (b)
606	                : (b == 0) ? ":%s(%2$dn)" // only step (a)
607	                : ":%s(%2$dn%3$+d)";      // step, offset
608	            String s = String.format(format, getPseudoClass(), a, b);
609	            if (filter != null) // render the of S clause inside the pseudo's parens: :nth-child(2n+1 of .p)
610	                s = s.substring(0, s.length() - 1) + " of " + filter + ")";
611	            return s;
612	        }
613	
614	        @Override
615	        protected void reset() {
616	            if (filter != null) filter.reset();
617	            super.reset();
618	        }
619	
620	        protected abstract String getPseudoClass();
621	
622	        protected abstract int calculatePosition(Element root, Element element);
623	    }
624	
