626	    /**
627	     * css-compatible Evaluator for :eq (css :nth-child)
628	     *
629	     * @see IndexEquals
630	     */
631	    public static final class IsNthChild extends CssNthEvaluator {
632	        public IsNthChild(int step, int offset) {
633	            super(step, offset);
634	        }
635	
636	        public IsNthChild(int step, int offset, @Nullable Evaluator filter) {
637	            super(step, offset, filter);
638	        }
639	
640	        @Override
641	        protected int calculatePosition(Element root, Element element) {
642	            if (filter == null)
643	                return element.elementSiblingIndex() + 1;
644	
645	            // position among the element siblings matching the of S filter, counted from 1
646	            Element parent = element.parent();
647	            int pos = 0;
648	            for (Element sibling = parent.firstElementChild();
649	                 sibling != null;
650	                 sibling = sibling.nextElementSibling()) {
651	                if (filter.matches(root, sibling)) pos++;
652	                if (sibling == element) break;
653	            }
654	            return pos;
655	        }
656	
657	        @Override
658	        protected String getPseudoClass() {
659	            return "nth-child";
660	        }
661	    }
