663	    /**
664	     * css pseudo class :nth-last-child)
665	     *
666	     * @see IndexEquals
667	     */
668	    public static final class IsNthLastChild extends CssNthEvaluator {
669	        public IsNthLastChild(int step, int offset) {
670	            super(step, offset);
671	        }
672	
673	        public IsNthLastChild(int step, int offset, @Nullable Evaluator filter) {
674	            super(step, offset, filter);
675	        }
676	
677	        @Override
678	        protected int calculatePosition(Element root, Element element) {
679	            if (filter == null) {
680	                if (element.parent() == null) return 0;
681	                return element.parent().childrenSize() - element.elementSiblingIndex();
682	            }
683	
684	            // position among the element siblings matching the of S filter, counted backwards from 1
685	            int pos = 0;
686	            for (Element sibling = element;
687	                 sibling != null;
688	                 sibling = sibling.nextElementSibling()) {
689	                if (filter.matches(root, sibling)) pos++;
690	            }
691	            return pos;
692	        }
693	
694			@Override
695			protected String getPseudoClass() {
696				return "nth-last-child";
697			}
698	    }
