700	    /**
701	     * css pseudo class nth-of-type
702	     *
703	     */
704	    public static class IsNthOfType extends CssNthEvaluator {
705	        public IsNthOfType(int step, int offset) {
706	            super(step, offset);
707	        }
708	
709	        @Override protected int calculatePosition(Element root, Element element) {
710	            Element parent = element.parent();
711	            if (parent == null)
712	                return 0;
713	
714	            int pos = 0;
715	            final int size = parent.childNodeSize();
716	            for (int i = 0; i < size; i++) {
717	                Node node = parent.childNode(i);
718	                if (node.normalName().equals(element.normalName())) pos++;
719	                if (node == element) break;
720	            }
721	            return pos;
722	        }
723	
724	        @Override
725	        protected String getPseudoClass() {
726	            return "nth-of-type";
727	        }
728	    }
