11	/**
12	 * Internal support for the {@code :scope} pseudo-class.
13	 * <p>{@code :scope} binds to the {@code root} element passed into an Evaluator's {@link Evaluator#matches matches()},
14	 * which is the element on which {@link Element#select(String)} was invoked. It holds no element itself, so a compiled
15	 * Evaluator can be reused against different roots, and a {@code :scope} nested in a {@code :has()} binds to that
16	 * {@code :has()} candidate, because {@link StructuralEvaluator.Has} supplies the candidate as the matching root for its
17	 * inner branches.</p>
18	 * <p>This class centralizes the two pieces of bookkeeping the engine needs:</p>
19	 * <ul>
20	 *   <li>{@link #validate} enforces that at most one {@code :scope} appears per scope level. The top-level selector is
21	 *   one level; each {@code :has()} argument establishes a new level (its anchor is the owning candidate). {@code :is()},
22	 *   {@code :not()} and the {@code of S} clause of {@code :nth-child()} establish no level and bind to the enclosing
23	 *   root;</li>
24	 *   <li>{@link #siblingBranches} isolates the top-level branches that lead with a scope-headed {@code +} or {@code ~}
25	 *   edge, so the {@link Collector} can additionally test just those branches against the anchor's following element
26	 *   siblings (required by {@code :scope + ...} and {@code :scope ~ ...}); the structural evaluators' own root guards
27	 *   ensure nothing above the anchor can ever match.</li>
28	 * </ul>
29	 */
30	final class ScopeSelector {
31	    private ScopeSelector() {}
32	
33	    /**
34	     * Validate that {@code :scope} occurs at most once per scope level: once in the top-level selector list, and once in
35	     * each nested {@code :has()} argument. {@code :is()}, {@code :not()} and the {@code of S} clause of
36	     * {@code :nth-child()} are transparent (they bind to the enclosing root). A {@code :scope} after a combinator (e.g.
37	     * {@code p + :scope}) is syntactically valid but can match nothing, as in a browser scoped query: the only candidate
38	     * equal to the root is the root itself, and structural edges never walk to or above it.
39	     * @param group the fully parsed evaluator
40	     * @param query the original selector text, for error messages
41	     * @throws Selector.SelectorParseException if a level contains more than one {@code :scope}
42	     */
43	    static void validate(Evaluator group, String query) {
44	        if (countAtLevel(group, query) > 1)
45	            throw new Selector.SelectorParseException(
46	                "Could not parse query '%s': the :scope pseudo-class may appear only once per selector level", query);
47	    }
48	
49	    /**
50	     * Count {@code :scope} tokens bound to the enclosing level's root, and recursively validate each {@code :has()}
51	     * subtree as a new level.
52	     */
53	    private static int countAtLevel(Evaluator eval, String query) {
54	        if (eval instanceof Evaluator.IsScope)
55	            return 1;
56	        if (eval instanceof StructuralEvaluator.Has) {
57	            if (countAtLevel(((StructuralEvaluator) eval).evaluator, query) > 1)
58	                throw new Selector.SelectorParseException(
59	                    "Could not parse query '%s': the :scope pseudo-class may appear only once per selector level", query);
60	            return 0; // its :scope tokens bind to the :has candidate, a different level
61	        }
62	        if (eval instanceof CombiningEvaluator) {
63	            int count = 0;
64	            for (Evaluator child : ((CombiningEvaluator) eval).evaluators)
65	                count += countAtLevel(child, query);
66	            return count;
67	        }
68	        if (eval instanceof StructuralEvaluator.ImmediateParentRun) {
69	            int count = 0;
70	            for (Evaluator child : ((StructuralEvaluator.ImmediateParentRun) eval).evaluators)
71	                count += countAtLevel(child, query);
72	            return count;
73	        }
74	        if (eval instanceof StructuralEvaluator) { // Ancestor, sibling edges, Is, Not: same level
75	            return countAtLevel(((StructuralEvaluator) eval).evaluator, query);
76	        }
77	        if (eval instanceof Evaluator.CssNthEvaluator) {
78	            Evaluator filter = ((Evaluator.CssNthEvaluator) eval).filter;
79	            return filter == null ? 0 : countAtLevel(filter, query);
80	        }
81	        return 0;
82	    }
83	
84	    /**
85	     * Whether the given compound selector is anchored by {@code :scope}: a single simple sequence that contains
86	     * {@code :scope} alongside type/id/class/attribute/pseudo refinements (as in {@code div:scope.x} or
87	     * {@code *:scope}), or is wrapped in a transparent {@code :is(...)}. A structural edge (descendant/child/sibling)
88	     * is never nested inside a single compound, and a {@code :has()} subtree delimits a different level, so neither
89	     * qualifies. The synthetic {@link StructuralEvaluator.Root} produced by a leading-combinator query (e.g.
90	     * {@code > p}) is not {@code :scope}.
91	     */
92	    static boolean isScopeAnchor(Evaluator edge) {
93	        if (edge instanceof Evaluator.IsScope)
94	            return true;
95	        if (edge instanceof CombiningEvaluator.Or) { // e.g. :is(:scope, p): any scope-headed branch anchors
96	            for (Evaluator branch : ((CombiningEvaluator.Or) edge).evaluators)
97	                if (isScopeAnchor(branch)) return true;
98	            return false;
99	        }
100	        if (edge instanceof CombiningEvaluator.And) {
101	            for (Evaluator member : ((CombiningEvaluator.And) edge).evaluators) {
102	                if (member instanceof StructuralEvaluator.Is) {
103	                    if (isScopeAnchor(((StructuralEvaluator.Is) member).evaluator)) return true;
104	                } else if (member instanceof Evaluator.IsScope) {
105	                    return true;
106	                }
107	                // any other member (tag, id, class, attribute, other pseudo, :has/:not) does not anchor the compound
108	            }
109	            return false;
110	        }
111	        if (edge instanceof StructuralEvaluator.Is)
112	            return isScopeAnchor(((StructuralEvaluator.Is) edge).evaluator);
113	        return false;
114	    }
115	
116	    /**
117	     * Whether the given evaluator references its matching root through {@code :scope} at its own level (a
118	     * {@code :scope} inside a nested {@code :has()} binds to that {@code :has()} candidate and is resolved there, so it
119	     * does not count).
120	     */
121	    static boolean usesScope(Evaluator eval) {
122	        if (eval instanceof Evaluator.IsScope)
123	            return true;
124	        if (eval instanceof StructuralEvaluator.Has)
125	            return false;
126	        if (eval instanceof CombiningEvaluator) {
127	            for (Evaluator child : ((CombiningEvaluator) eval).evaluators)
128	                if (usesScope(child)) return true;
129	            return false;
130	        }
131	        if (eval instanceof StructuralEvaluator.ImmediateParentRun) {
132	            for (Evaluator child : ((StructuralEvaluator.ImmediateParentRun) eval).evaluators)
133	                if (usesScope(child)) return true;
134	            return false;
135	        }
136	        if (eval instanceof StructuralEvaluator)
137	            return usesScope(((StructuralEvaluator) eval).evaluator);
138	        if (eval instanceof Evaluator.CssNthEvaluator) {
139	            Evaluator filter = ((Evaluator.CssNthEvaluator) eval).filter;
140	            return filter != null && usesScope(filter);
141	        }
142	        return false;
143	    }
144	
145	    /**
146	     * Trace a branch's left-most combinator chain and report its leading sibling axis when that axis starts at
147	     * {@code :scope}. This mirrors {@link StructuralEvaluator.Has#siblingAxis branch axis detection} but recognizes a
148	     * {@code :scope} terminus (possibly classified or wrapped in {@code :is()}) rather than only the synthetic
149	     * {@link StructuralEvaluator.Root}.
150	     * @return {@code '+'}, {@code '~'}, or {@code 0} when the branch is not a scope-headed sibling branch
151	     */
152	    private static char scopeSiblingAxis(Evaluator branch) {
153	        Evaluator edge = branch;
154	        while (true) {
155	            if (edge instanceof CombiningEvaluator.And) {
156	                edge = ((CombiningEvaluator.And) edge).evaluators.get(0);
157	            } else if (edge instanceof StructuralEvaluator.ImmediateParentRun) {
158	                edge = ((StructuralEvaluator.ImmediateParentRun) edge).evaluators.get(0);
159	            } else if (edge instanceof StructuralEvaluator.Ancestor) {
160	                edge = ((StructuralEvaluator.Ancestor) edge).evaluator;
161	            } else if (edge instanceof StructuralEvaluator.ImmediatePreviousSibling) {
162	                Evaluator left = ((StructuralEvaluator) edge).evaluator;
163	                if (isScopeAnchor(left)) return '+';
164	                edge = left; // a chained sibling combinator; continue to the left-most edge
165	            } else if (edge instanceof StructuralEvaluator.PreviousSibling) {
166	                Evaluator left = ((StructuralEvaluator) edge).evaluator;
167	                if (isScopeAnchor(left)) return '~';
168	                edge = left;
169	            } else if (edge instanceof StructuralEvaluator.Is) {
170	                edge = ((StructuralEvaluator.Is) edge).evaluator;
171	            } else {
172	                return 0;
173	            }
174	        }
175	    }
176	
177	    /**
178	     * Build an evaluator containing only the top-level branches that lead with a {@code :scope}-headed {@code +} or
179	     * {@code ~} sibling edge. Those are the only branches allowed to match among the root's following siblings and
180	     * their subtrees; every other branch stays confined to the root and its descendants, preserving the historical
181	     * descendants-only behavior of queries that do not use {@code :scope}. Returns {@code null} when there is no such
182	     * branch.
183	     */
184	    static @Nullable Evaluator siblingBranches(Evaluator eval) {
185	        List<Evaluator> matches = new ArrayList<>();
186	        if (eval instanceof CombiningEvaluator.Or) {
187	            for (Evaluator branch : ((CombiningEvaluator.Or) eval).evaluators) {
188	                if (scopeSiblingAxis(branch) != 0)
189	                    matches.add(branch);
190	            }
191	        } else if (scopeSiblingAxis(eval) != 0) {
192	            matches.add(eval);
193	        }
194	        if (matches.isEmpty())
195	            return null;
196	        if (matches.size() == 1)
197	            return matches.get(0);
198	        return new CombiningEvaluator.Or(matches);
199	    }
200	
201	    /** How much of the root's following-sibling axis a set of scope-headed sibling branches must search. */
202	    private enum Breadth {
203	        /** only the root's immediate following sibling. */
204	        Immediate,
205	        /** every following sibling, but not their descendants. */
206	        Siblings,
207	        /** every following sibling and the full subtree beneath each. */
208	        Subtrees
209	    }
210	
211	    /**
212	     * The narrowest candidate breadth covering all scope-headed sibling branches: a non-deep {@code +} branch needs
213	     * only the immediate sibling, a non-deep {@code ~} branch the following siblings themselves, and a branch that
214	     * chains a further combinator must search sibling subtrees.
215	     */
216	    private static Breadth siblingBreadth(Evaluator siblingEval) {
217	        List<Evaluator> branches = new ArrayList<>();
218	        if (siblingEval instanceof CombiningEvaluator.Or)
219	            branches.addAll(((CombiningEvaluator.Or) siblingEval).evaluators);
220	        else
221	            branches.add(siblingEval);
222	
223	        Breadth breadth = Breadth.Immediate;
224	        for (Evaluator branch : branches) {
225	            Breadth needed = deepSiblingBranch(branch) ? Breadth.Subtrees
226	                : scopeSiblingAxis(branch) == '+' ? Breadth.Immediate : Breadth.Siblings;
227	            if (needed.ordinal() > breadth.ordinal())
228	                breadth = needed;
229	        }
230	        return breadth;
231	    }
232	
233	    /**
234	     * Whether a scope-headed sibling branch chains another combinator after its leading edge (e.g.
235	     * {@code :scope + article > img}), so its target may lie within a sibling's subtree. Mirrors
236	     * {@link StructuralEvaluator.Has}'s chain detection, treating {@code :scope} as the anchor terminus.
237	     */
238	    private static boolean deepSiblingBranch(Evaluator eval) {
239	        if (eval instanceof StructuralEvaluator.Ancestor)
240	            return true;
241	        if (eval instanceof StructuralEvaluator.ImmediateParentRun)
242	            return ((StructuralEvaluator.ImmediateParentRun) eval).evaluators.size() > 1;
243	        if (eval instanceof StructuralEvaluator.ImmediatePreviousSibling
244	            || eval instanceof StructuralEvaluator.PreviousSibling) {
245	            Evaluator left = ((StructuralEvaluator) eval).evaluator;
246	            return !(left instanceof StructuralEvaluator.Root || isScopeAnchor(left));
247	        }
248	        if (eval instanceof CombiningEvaluator) {
249	            for (Evaluator child : ((CombiningEvaluator) eval).evaluators)
250	                if (deepSiblingBranch(child)) return true;
251	        }
252	        return false; // a plain compound, or a self-contained evaluator (Is, Not, nested Has)
253	    }
254	
255	    /**
256	     * The root's following element siblings required by the scope-headed sibling branches, in document order and
257	     * including each sibling's own subtree only when necessary. Non-element siblings are skipped: element
258	     * relationships never count them. The tree is only read.
259	     */
260	    static Stream<Element> siblingElements(Evaluator siblingEval, Element root) {
261	        Breadth breadth = siblingBreadth(siblingEval);
262	        if (breadth == Breadth.Immediate) {
263	            Element sibling = root.nextElementSibling();
264	            return sibling == null ? Stream.empty() : Stream.of(sibling);
265	        }
266	        Stream.Builder<Stream<Element>> streams = Stream.builder();
267	        for (Element sibling = root.nextElementSibling(); sibling != null; sibling = sibling.nextElementSibling())
268	            streams.add(breadth == Breadth.Subtrees ? sibling.stream() : Stream.of(sibling));
269	        return streams.build().flatMap(stream -> stream);
270	    }
271	
272	    /**
273	     * Node-typed variant of {@link #siblingElements}. A branch that uses only element selectors keeps element
274	     * relationship semantics (non-element siblings are skipped, as in {@code :scope + p}); a branch that requests nodes
275	     * (e.g. {@code :scope + ::comment}) walks raw node siblings, and an element sibling in a subtree search carries its
276	     * descendant nodes.
277	     */
278	    static <T extends Node> Stream<T> siblingNodes(Evaluator siblingEval, Element root, Class<T> type) {
279	        if (!siblingEval.wantsNodes())
280	            return siblingElements(siblingEval, root).filter(type::isInstance).map(type::cast);
281	
282	        Breadth breadth = siblingBreadth(siblingEval);
283	        Stream.Builder<Node> siblings = Stream.builder();
284	        if (breadth == Breadth.Immediate) {
285	            Node next = root.nextSibling();
286	            if (next != null) siblings.add(next);
287	        } else {
288	            for (Node sibling = root.nextSibling(); sibling != null; sibling = sibling.nextSibling())
289	                siblings.add(sibling);
290	        }
291	        return siblings.build().flatMap(node -> {
292	            Stream<? extends Node> nodes = breadth == Breadth.Subtrees && node instanceof Element
293	                ? ((Element) node).nodeStream(Node.class)
294	                : Stream.of(node);
295	            return nodes.filter(type::isInstance).map(type::cast);
296	        });
297	    }
298	}
