package org.jsoup.select;

import org.jsoup.Jsoup;
import org.jsoup.nodes.Document;
import org.jsoup.nodes.Element;
import org.junit.jupiter.api.Test;

import static org.junit.jupiter.api.Assertions.*;

class ScratchNthOfTest {

    @Test void mutationLiveRenumber() {
        String html = "<ul><li id=a class=p></li><li id=b></li><li id=c class=p></li></ul>";
        Document doc = Jsoup.parse(html);
        Evaluator ev = Selector.evaluatorOf("li:nth-child(2 of .p)");

        assertEquals("c", doc.select(ev).attr("id"));
        assertEquals("c", doc.select(ev).attr("id")); // stable repeat

        // remove the first matching sibling -> c becomes position 1, nothing at 2
        doc.getElementById("a").remove();
        assertTrue(doc.select(ev).isEmpty(), doc.select(ev).toString());

        // restore via DOM add, re-evaluate immediately
        doc.selectFirst("ul").appendElement("li").attr("id", "d").attr("class", "p");
        // siblings now: b, c, d => .p positions: c=1 d=2
        assertEquals("d", doc.select(ev).attr("id"));

        // mutate the class the filter depends on
        doc.getElementById("c").removeClass("p");
        // .p: d only -> position 2 empty
        assertTrue(doc.select(ev).isEmpty());
        doc.getElementById("c").addClass("p");
        assertEquals("d", doc.select(ev).attr("id"));
    }

    @Test void scopeInFilter() {
        String html = "<div id=r><ul><li id=a class=p></li><li id=b></li><li id=c class=p></li></ul></div>";
        Document doc = Jsoup.parse(html);
        Element r = doc.getElementById("r");
        // :scope in S binds to the select root
        assertEquals("a", r.selectFirst("li:nth-child(1 of :scope li.p)").id());
        assertEquals("c", r.selectFirst("li:nth-child(2 of :scope li.p)").id());

        // :scope in each branch of the S list, anchor is the enumerated sibling
        Element ul = doc.selectFirst("ul");
        String q = "li:nth-child(2 of .p:not(:scope > *))"; // siblings are li, children of ul; :scope is r, li is not a direct child -> all filtered out
        // actually r>ul>li: li is not direct child of r, so :not(:scope>*) keeps them. just ensure it parses & runs
        assertDoesNotThrow(() -> ul.select(q));
    }

    @Test void hasInFilterMutation() {
        Document doc = Jsoup.parse(
            "<ul><li id=a><i></i></li><li id=b></li><li id=c><i></i></li></ul>");
        Evaluator ev = Selector.evaluatorOf("li:nth-child(2 of li:has(i))");
        assertEquals("c", doc.select(ev).attr("id"));
        doc.selectFirst("#a i").remove();
        // now only c has i -> position 1, pos 2 empty
        assertTrue(doc.select(ev).isEmpty());
        doc.selectFirst("#b").appendElement("i");
        // b and c have i; b=1 c=2
        assertEquals("c", doc.select(ev).attr("id"));
    }

    @Test void nonElementNodesIgnored() {
        // comments and text between must not change adjacency/counting
        Document doc = Jsoup.parse("<ul><!--c1--><li id=a class=p>x</li>txt<li id=b class=p>y</li></ul>");
        assertEquals("b", doc.select("li:nth-child(2 of .p)").attr("id"));
        assertEquals("a", doc.select("li:nth-last-child(2 of .p)").attr("id"));
    }

    @Test void candidateMustMatchFilter() {
        Document doc = Jsoup.parse("<ul><li id=a class=p></li><li id=b></li></ul>");
        // b is the 2nd element sibling but doesn't match .p -> no match
        assertFalse(doc.getElementById("b").is("li:nth-child(1 of .p)"));
    }

    @Test void invalidSyntax() {
        String[] invalid = {
            "li:nth-child(2n of)",
            "li:nth-child(2 ofof .p)",   // 'ofof' should be treated as part? formula '2' then trailing -> fail
            "li:nth-child(2 of :bogus(.p))",
            "li:nth-child(2 of .p >)",     // dangling combinator in S
            "li:nth-child(2 of .p,)",      // empty branch
            "li:nth-child(2 of .p, )",
            "li:nth-child(2 of)",
            "li:nth-child( of .p)",
            "li:nth-child(2x+1 of .p)",
            "li:nth-child(n2 of .p)",
            "li:nth-child(2 of [attr)",
            "li:nth-child(2 of .p,",
            ":nth-child(2 of ::bogus)",
            ":nth-child(2 of .p .)",
        };
        for (String q : invalid) {
            assertThrows(Selector.SelectorParseException.class, () -> Selector.evaluatorOf(q), q);
        }
    }

    @Test void validEdgeCases() {
        // "of" as attribute value must not be split
        Document doc = Jsoup.parse("<ul><li id=a data-x='of foo'></li></ul>");
        assertDoesNotThrow(() -> Selector.evaluatorOf("li:nth-child(1 of [data-x='of foo'])"));
        assertEquals("a", doc.select("li:nth-child(1 of [data-x='of foo'])").attr("id"));

        // whitespace around formula
        Document doc2 = Jsoup.parse("<ul><li id=a class=p></li><li id=b class=p></li></ul>");
        assertEquals("a", doc2.select("li:nth-child( 1 of .p )").attr("id"));
        assertEquals("b", doc2.select("li:nth-child(odd  of  .p)").last().attr("id"));
    }

    @Test void combinedWithOtherSelectorsAndDedup() {
        Document doc = Jsoup.parse(
            "<div><p class=x id=a></p><p class=x id=b></p></div>");
        // comma merge dedup: same element via two branches, once, doc order
        Elements els = doc.select("p:nth-child(1 of .x), p#x, p:not(span)");
        assertEquals(2, els.size());
        assertEquals("a", els.get(0).id());
        assertEquals("b", els.get(1).id());
    }

    @Test void unchangedSemanticsWithoutOf() {
        Document doc = Jsoup.parse("<ul><li id=a></li> x <li id=b></li></ul>");
        assertEquals("a", doc.select("li:nth-child(odd)").first().id());
        assertEquals("b", doc.select("li:nth-last-child(1)").first().id());
        assertEquals("b", doc.select("li:nth-child(2)").first().id());
    }
}

