    @Test void candidateMustMatchFilter() {
        Document doc = Jsoup.parse("<ul><li id=a class=p></li><li id=b></li></ul>");
        // b is the 2nd element sibling but doesn't match .p -> no match
        assertFalse(doc.getElementById("b").is("li:nth-child(1 of .p)"));
    }

    @Test void invalidSyntax() {
        String[] invalid = {
            "li:nth-child(2n of)",
            "li:nth-child(2 ofof .p)",   // 'ofof' should be treated as part? formula '2' then trailing -> fail
            "li:nth-child(2 of :bogus(.p))",
            "li:nth-child(2 of .p >)",     // dangling combinator in S
            "li:nth-child(2 of .p,)",      // empty branch
            "li:nth-child(2 of .p, )",
            "li:nth-child(2 of)",
            "li:nth-child( of .p)",
            "li:nth-child(2x+1 of .p)",
            "li:nth-child(2 of [attr)",
            "li:nth-child(2 of .p,",
            ":nth-child(2 of ::bogus)",
            ":nth-child(2 of .p .)",
        };
        for (String q : invalid) {
            assertThrows(Selector.SelectorParseException.class, () -> Selector.evaluatorOf(q), q);
        }
    }

    @Test void validEdgeCases() {
        // "of" as attribute value must not be split
        Document doc = Jsoup.parse("<ul><li id=a data-x='of foo'></li></ul>");
        assertDoesNotThrow(() -> Selector.evaluatorOf("li:nth-child(1 of [data-x='of foo'])"));
        assertEquals("a", doc.select("li:nth-child(1 of [data-x='of foo'])").attr("id"));

        // whitespace around formula
        Document doc2 = Jsoup.parse("<ul><li id=a class=p></li><li id=b class=p></li></ul>");
        assertEquals("a", doc2.select("li:nth-child( 1 of .p )").attr("id"));
        assertEquals("b", doc2.select("li:nth-child(odd  of  .p)").last().attr("id"));
    }

    @Test void combinedWithOtherSelectorsAndDedup() {
        Document doc = Jsoup.parse(
            "<div><p class=x id=a></p><p class=x id=b></p></div>");
        // comma merge dedup: same element via two branches, once, doc order
        Elements els = doc.select("p:nth-child(1 of .x), p#x, p:not(span)");
        assertEquals(2, els.size());
        assertEquals("a", els.get(0).id());
        assertEquals("b", els.get(1).id());
    }

    @Test void unchangedSemanticsWithoutOf() {
        Document doc = Jsoup.parse("<ul><li id=a></li> x <li id=b></li></ul>");
        assertEquals("a", doc.select("li:nth-child(odd)").first().id());
        assertEquals("b", doc.select("li:nth-last-child(1)").first().id());
        assertEquals("b", doc.select("li:nth-child(2)").first().id());
    }
}

