package org.jsoup.select;

import org.jsoup.Jsoup;
import org.jsoup.nodes.Document;
import org.jsoup.nodes.Element;
import org.junit.jupiter.api.Test;

import static org.junit.jupiter.api.Assertions.*;

class ScratchMemoTest {
    @Test void reusedEvaluatorIsAfterMutation() {
        // Baseline: does a plain :not() go stale under is() with a reused evaluator?
        Document doc = Jsoup.parse("<p id=x class=y></p>");
        Element x = doc.getElementById("x");
        Evaluator plain = Selector.evaluatorOf("p:not(.z)");
        System.out.println("plain before: " + x.is(plain));
        x.addClass("z");
        System.out.println("plain after addClass z: " + x.is(plain) + " (expected false)");

        // nth-of-S with :not in filter, reused under is()
        Document doc2 = Jsoup.parse("<ul><li id=a class=p></li><li id=b></li><li id=c class=p></li></ul>");
        Evaluator ev = Selector.evaluatorOf("li:nth-child(2 of li:not(.gone))");
        Element c = doc2.getElementById("c");
        System.out.println("nth before: " + c.is(ev) + " (expected true)");
        doc2.getElementById("a").addClass("gone");
        System.out.println("nth after a.gone: " + c.is(ev) + " (expected false: c now pos1 among non-gone)");

        // :has inside filter under is reuse
        Evaluator ev2 = Selector.evaluatorOf("li:nth-child(2 of li:has(i))");
        Document doc3 = Jsoup.parse("<ul><li id=a><i></i></li><li id=c><i></i></li></ul>");
        Element c3 = doc3.getElementById("c");
        System.out.println("has before: " + c3.is(ev2) + " (expected true)");
        doc3.selectFirst("#a i").remove();
        System.out.println("has after remove: " + c3.is(ev2) + " (expected false)");
    }
}

