package org.jsoup.select;

import org.jsoup.Jsoup;
import org.jsoup.nodes.Document;
import org.jsoup.nodes.Element;
import org.junit.jupiter.api.Test;

import static org.junit.jupiter.api.Assertions.*;

class ScratchSpecTest {
    @Test void taskExample() {
        // li:nth-child(2n+1 of .ready, [data-kind=card]) numbers only qualifying li's
        Document doc = Jsoup.parse(
            "<ul>" +
            "<li class='ad' data-kind=ad>ad</li>" +      // hidden ad: not in filter set
            "<li class='ready' id=a>A</li>" +            // ready #1 (odd) -> match
            "<li data-kind=card id=b>B</li>" +           // card #2 (even)
            "<li disabled id=skip>S</li>" +              // disabled, excluded implicitly by filter
            "<li class='ready' data-kind=card id=c>C</li>" + // matches both branches; counted once: #3 (odd)
            "<li class='ready' id=d>D</li>" +            // #4 (even)
            "</ul>");
        Elements got = doc.select("li:nth-child(2n+1 of .ready, [data-kind=card])");
        assertEquals(2, got.size());
        assertEquals("a", got.get(0).id());
        assertEquals("c", got.get(1).id());
    }

    @Test void moveSiblingsRenumbers() {
        Document doc = Jsoup.parse("<ul><li id=a class=p></li><li id=b class=p></li><li id=c class=p></li></ul>");
        Element a = doc.getElementById("a");
        Element ul = doc.selectFirst("ul");
        Evaluator ev = Selector.evaluatorOf("li:nth-child(1 of .p)");
        assertEquals("a", doc.select(ev).attr("id"));
        ul.appendChild(a); // move a to end: b, c, a
        assertEquals("b", doc.select(ev).attr("id"));
    }

    @Test void mixedElementTypesAndComments() {
        // direct element children only; text/comment/doctype-ish nodes ignored
        Document doc = Jsoup.parse(
            "<div>head<!--c--><span class=x id=a></span>txt<b class=x id=b></b><i class=x id=c></i></div>");
        Elements one = doc.select(".x:nth-child(1 of .x)");
        assertEquals(1, one.size());
        assertEquals("a", one.first().id());
        Elements last = doc.select(".x:nth-last-child(1 of .x)");
        assertEquals("c", last.first().id());
    }

    @Test void scopeAnchoredFilter() {
        Document doc = Jsoup.parse(
            "<div id=r><ul><li class=p id=a></li><li class=p id=b></li></ul><ol><li class=p id=c></li></ol></div>");
        Element r = doc.getElementById("r");
        // :scope li.p enumerates all li.p under r across both lists
        assertEquals("a", r.select("li:nth-child(1 of :scope li.p)").first().id());
        assertEquals("b", r.select("li:nth-child(2 of :scope li.p)").first().id());
        assertEquals("c", r.select("li:nth-child(3 of :scope li.p)").first().id());
    }
}

