@Test void scopeAnchoredFilter() {
    Document doc = Jsoup.parse(
        "<div id=r><ul><li class=p id=a></li><li class=p id=b></li></ul><ol><li class=p id=c></li></ol></div>");
    Element r = doc.getElementById("r");
    // S is anchored at :scope (r): only the li directly under r>ul qualifies; the li under ol does not.
    // Numbering still happens per-parent among the filtered sibling set.
    Elements ones = r.select("li:nth-child(1 of :scope > ul > li)");
    assertEquals(1, ones.size());
    assertEquals("a", ones.first().id());
    Elements twos = r.select("li:nth-child(2 of :scope > ul > li)");
    assertEquals(1, twos.size());
    assertEquals("b", twos.first().id());
    // c matches neither S itself nor any numbered slot: its parent is ol, not the scoped ul
    assertTrue(r.select("li:nth-child(1 of :scope > ul > li)").stream().noneMatch(e -> e.id().equals("c")));
    assertFalse(doc.getElementById("c").is(":nth-child(1 of :scope > ul > li)"));
}

